pub unsafe extern "C" fn isolat1ToUTF8(
    mut out: *mut c_uchar,
    mut outlen: *mut c_int,
    mut in_0: *const c_uchar,
    mut inlen: *mut c_int,
) -> c_int {
    if out.is_null() || in_0.is_null() || outlen.is_null() || inlen.is_null() {
        return XML_ENC_ERR_INTERNAL as c_int;
    }

    let out_cap_i32 = *outlen;
    let in_cap_i32 = *inlen;

    let out_cap = out_cap_i32 as usize;
    let in_cap = in_cap_i32 as usize;

    let outstart = out;
    let base = in_0;

    // SAFETY: the pointers were checked non-null above; lengths come from the
    // caller-provided `*outlen`/`*inlen` and are treated as stable for this
    // region; this creates one mutable output view and one immutable input view,
    // matching the original function's assumptions that these buffers are valid
    // for the stated lengths and not aliased in a way that violates Rust refs.
    let out_buf = unsafe { core::slice::from_raw_parts_mut(out, out_cap) };
    // SAFETY: the pointer was checked non-null above; length comes from the
    // caller-provided `*inlen` and is stable for this region; the resulting
    // shared slice matches the original read-only use of the input buffer.
    let in_buf = unsafe { core::slice::from_raw_parts(in_0, in_cap) };

    let mut in_pos = 0usize;
    let mut out_pos = 0usize;

    while in_pos < in_buf.len() && out_pos + 1 < out_buf.len() {
        let b = in_buf[in_pos];
        if b >= 0x80 {
            out_buf[out_pos] = (((b as c_int >> 6) & 0x1f) | 0xc0) as c_uchar;
            out_buf[out_pos + 1] = ((b as c_int & 0x3f) | 0x80) as c_uchar;
            out_pos += 2;
            in_pos += 1;
        }

        let remaining_out = out_buf.len() - out_pos;
        let remaining_in = in_buf.len() - in_pos;
        let ascii_stop = in_pos + core::cmp::min(remaining_in, remaining_out);

        while in_pos < ascii_stop {
            let b = in_buf[in_pos];
            if b >= 0x80 {
                break;
            }
            out_buf[out_pos] = b;
            in_pos += 1;
            out_pos += 1;
        }
    }

    if in_pos < in_buf.len() && out_pos < out_buf.len() {
        let b = in_buf[in_pos];
        if b < 0x80 {
            out_buf[out_pos] = b;
            in_pos += 1;
            out_pos += 1;
        }
    }

    out = outstart.wrapping_add(out_pos);
    in_0 = base.wrapping_add(in_pos);

    *outlen = out.offset_from(outstart) as c_int;
    *inlen = in_0.offset_from(base) as c_int;
    *outlen
